const rawInput = $json.output ?? $json.text ?? $json;

try {
  let parsed;

  if (typeof rawInput === 'object' && rawInput !== null) {
    parsed = rawInput;
  } else {
    const cleanJson = String(rawInput)
      .replace(/```json\s*/gi, '')
      .replace(/```\s*/g, '')
      .trim();
    parsed = JSON.parse(cleanJson);
  }

  const dadosFaltantes = Array.isArray(parsed.dados_faltantes)
    ? parsed.dados_faltantes.filter(Boolean)
    : [];

  const faltamDados = dadosFaltantes.length > 0;

  const pergunta = faltamDados
    ? (parsed.pergunta && parsed.pergunta.trim() !== ''
        ? parsed.pergunta.trim()
        : 'Por favor, descreva qual é o problema para que eu possa registrar o seu chamado.')
    : '';

  const webhook = $('Normalizar Webhook').first()?.json || {};
  const payload = $('Estruturar Payload').first()?.json || {};

  const chatId =
    webhook.chat_id ||
    webhook.chatId ||
    webhook.remoteJid ||
    webhook.telefone ||
    webhook.whatsapp ||
    payload.chat_id ||
    payload.chatId ||
    '';

  const relatoAtual =
    webhook.mensagem ||
    webhook.texto ||
    webhook.text ||
    webhook.body ||
    webhook.message ||
    webhook.conteudo ||
    payload.chamado?.relato_morador ||
    '';

  return {
    json: {
      chat_id: chatId,
      relato: relatoAtual,
      resumo: parsed.resumo || '',
      categoria: parsed.categoria || 'outros',
      prioridade: parsed.prioridade || 'media',
      dados_faltantes: dadosFaltantes,
      pergunta,
      motivo: parsed.motivo || '',
      faltam_dados: faltamDados,
      parse_success: true,
      raw_response: typeof rawInput === 'string' ? rawInput : JSON.stringify(rawInput)
    }
  };
} catch (error) {
  return {
    json: {
      parse_success: false,
      validacao_ok: false,
      faltam_dados: false,
      erro_parse: error.message,
      raw_response: typeof rawInput === 'string' ? rawInput : JSON.stringify(rawInput)
    }
  };
}

