const cmd = $('Parse_Consultar_Chamados').item.json || {};
const norm = $('Normalizar Webhook').item.json || {};
const chamado = $input.item.json || {};

const session = cmd.session || norm.session || 'default';
const chatId = cmd.chatId || norm.chat_id || norm.chatId || '';
const textoRaw = String(cmd.texto || cmd.message || norm.texto || norm.mensagem || '').trim();
const textoNorm = textoRaw
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

const temChamado = Boolean(chamado && chamado.protocolo);

// Identifica a intenção/comando do morador ou responsável
let comando = 'fallback';

if (!temChamado) {
  comando = 'sem_chamado';
} else if (/\b(status|andamento|acompanhar|situacao|consultar|consulta|meu chamado|meus chamados|protocolo)\b/.test(textoNorm)) {
  comando = 'status';
} else if (/\b(confirmar|confirmo|ok|ciente|recebido|aceito|de acordo)\b/.test(textoNorm)) {
  comando = 'confirmo';
} else if (/\b(resolvido|resolver|concluido|concluir|finalizado|finalizar|arrumado|pronto|solucionado)\b/.test(textoNorm)) {
  comando = 'resolvido';
} else if (/\b(reabrir|reabertura|voltou|continua|ainda nao|nao resolveu|pendente novamente)\b/.test(textoNorm)) {
  comando = 'reabrir';
} else if (/\b(cancelar|cancelamento|desistir|desisto|excluir|apagar|nao precisa mais)\b/.test(textoNorm)) {
  comando = 'cancelar';
}

return {
  json: {
    session,
    chatId,
    chat_id: chatId,
    comando,
    tem_chamado: temChamado,
    texto: textoRaw,
    protocolo: chamado.protocolo || cmd.protocolo || '',
    status_atual: chamado.status || '',
    resumo: chamado.resumo || '',
    relato: chamado.relato_morador || chamado.relato || '',
    unidade: chamado.unidade || '',
    morador_bloco: chamado.morador_bloco || cmd.bloco || '',
    morador_andar: chamado.morador_andar || cmd.andar || '',
    morador_apartamento: chamado.morador_apartamento || cmd.apartamento || '',
    morador_nome: chamado.morador_nome || '',
    morador_whatsapp: chamado.morador_whatsapp || cmd.morador_whatsapp || '',
    responsavel: chamado.responsavel || 'Equipe da Portaria',
    responsavel_whatsapp: chamado.responsavel_whatsapp || '',
    responsavel_chat_id: chamado.responsavel_chat_id || '',
    data_abertura: chamado.data_abertura || chamado.criado_em || ''
  }
};

