const norm = $('Normalizar Webhook').item.json || {};
const payload = $('Estruturar Payload').item.json || {};
const morador = payload.morador || {};
const encomendaPayload = payload.encomenda || {};
const triagem = $('Agente Triagem').item.json?.output || $('Agente Triagem').item.json || {};

const textoRaw = String(
  norm.mensagem || norm.texto || norm.text || norm.chamado_relato || ''
).trim();

const textoNorm = textoRaw
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

let acao = triagem.acao_encomenda || 'confirmar_leitura';
if (/\b(recebi|retirei|peguei|ja peguei)\b/.test(textoNorm)) {
  acao = 'confirmar_retirada';
} else if (/\b(ok|li|ciente)\b/.test(textoNorm)) {
  acao = 'confirmar_leitura';
}

return {
  json: {
    session: norm.session || 'default',
    chat_id: norm.chat_id || '',
    texto: textoRaw,
    acao,
    protocolo: encomendaPayload.protocolo || '',
    codigo_retirada: triagem.codigo_retirada || encomendaPayload.codigo_retirada || '',
    morador_bloco: morador.bloco || '',
    morador_andar: morador.andar || '',
    morador_apartamento: morador.apartamento || '',
    morador_nome: morador.nome || '',
    morador_whatsapp: morador.whatsapp || ''
  }
};

// Leitura segura dos nós anteriores (funciona tanto via webhook quanto via execução manual EF_Consultar_Chamados)
const manual = $('EF_Consultar_Chamados').isExecuted ? ($('EF_Consultar_Chamados').first().json || {}) : {};
const norm = $('Normalizar Webhook').isExecuted ? ($('Normalizar Webhook').first().json || {}) : {};
const payload = $('Estruturar Payload').isExecuted ? ($('Estruturar Payload').first().json || {}) : {};
const moradorDb = $('Filtra Morador').isExecuted ? ($('Filtra Morador').first().json || {}) : {};
const geminiOut = $('Extrair Dados IA').isExecuted ? ($('Extrair Dados IA').first().json?.output || {}) : {};
const rawBody = $json.body || {};

// 1. Identificação do usuário e sessão
const session = manual.session || norm.session || 'default';

const chatId =
  manual.chatId ||
  norm.chat_id ||
  norm.chatId ||
  geminiOut.identificador_usuario ||
  rawBody.TargetChat ||
  rawBody.TargetSender ||
  '';

const moradorWhatsapp =
  manual.morador_whatsapp ||
  norm.morador_whatsapp ||
  norm.whatsapp ||
  norm.telefone ||
  geminiOut.identificador_usuario ||
  rawBody.TargetSender ||
  chatId ||
  '';

// Dados cadastrais do morador (para garantir consulta mesmo quando chatId vier como @lid)
const bloco = payload.morador?.bloco || moradorDb.bloco || '';
const andar = payload.morador?.andar || moradorDb.andar || '';
const apartamento = payload.morador?.apartamento || moradorDb.apartamento || '';

// 2. Texto da mensagem recebida
const texto = String(
  manual.message ||
  manual.texto ||
  norm.texto ||
  norm.mensagem ||
  norm.body ||
  rawBody.Message?.conversation ||
  rawBody.RawMessage?.conversation ||
  ''
).trim();

// 3. Extrai protocolo UUID se o morador tiver informado na mensagem
const uuidMatch = texto.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
const protocolo = uuidMatch
  ? uuidMatch[0]
  : (manual.protocolo || payload.chamado?.protocolo || '');

return [
  {
    json: {
      session,
      chatId,
      chat_id: chatId,
      morador_whatsapp: moradorWhatsapp,
      bloco,
      andar,
      apartamento,
      texto,
      message: texto,
      protocolo
    }
  }
];

const itemAtual = $input.first().json;

// 1. Busca segura do payload base (mantém seus UUIDs, protocolo, codigo_retirada e datas originais)
let base = null;
const nomesPossiveis = ['Estruturar Payload', 'Code in JavaScript'];

for (const nome of nomesPossiveis) {
  try {
    const encontrado = $(nome).first()?.json;
    if (encontrado && encontrado.contexto && encontrado.encomenda) {
      base = encontrado;
      break;
    }
  } catch (e) {}
}

if (!base) {
  base = {
    contexto: itemAtual.contexto || {},
    morador: {
      id: null, nome: null, whatsapp: null, endereco: null,
      apartamento: null, andar: null, bloco: null, complemento: null, ativo: null
    },
    encomenda: itemAtual.encomenda || {},
    chamado: itemAtual.chamado || {}
  };
}

// 2. Extrai o JSON retornado pelo agente
const rawOutput =
  itemAtual.output ??
  itemAtual.text ??
  itemAtual.response ??
  itemAtual.content ??
  itemAtual;

let ia = {};
if (typeof rawOutput === 'object' && rawOutput !== null && !rawOutput.contexto) {
  ia = rawOutput;
} else if (typeof rawOutput === 'string') {
  try {
    const limpo = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();
    const match = limpo.match(/\{[\s\S]*\}/);
    ia = match ? JSON.parse(match[0]) : {};
  } catch (e) {
    ia = {};
  }
}

// Helper: converte strings vazias "" ou espaços em null
const limparTexto = (valor) => {
  if (valor === undefined || valor === null) return null;
  const texto = String(valor).trim();
  return texto.length > 0 ? texto : null;
};

const imagemLegivel = Boolean(ia.imagem_legivel);

// 3. Recupera o arquivo binário da imagem baixada (caso exista)
let binaryData = undefined;
try {
  binaryData = $('Baixar Imagem1').first()?.binary;
} catch (e) {}

// 4. Monta o objeto consolidado final
const resultado = {
  json: {
    ...base,
    contexto: {
      ...base.contexto,
      imagem_legivel: imagemLegivel
    },
    encomenda: {
      ...base.encomenda,
      destinatario_nome: limparTexto(ia.destinatario_nome) ?? base.encomenda.destinatario_nome ?? null,
      destinatario_apartamento: limparTexto(ia.destinatario_apartamento) ?? base.encomenda.destinatario_apartamento ?? null,
      destinatario_bloco: limparTexto(ia.destinatario_bloco) ?? base.encomenda.destinatario_bloco ?? null,
      destinatario_andar: limparTexto(ia.destinatario_andar) ?? base.encomenda.destinatario_andar ?? null,
      destinatario_endereco: limparTexto(ia.destinatario_endereco) ?? base.encomenda.destinatario_endereco ?? null,
      dados_remetente: limparTexto(ia.dados_remetente) ?? base.encomenda.dados_remetente ?? null,
      imagem_legivel: imagemLegivel
    }
  }
};

if (binaryData) {
  resultado.binary = binaryData;
}

return [resultado];

