// 1. Recupera o estado completo consolidado antes da consulta ao banco
const base = $('Consolidar Dados').first().json;

// 2. Captura o resultado retornado pelo nó "Buscar Morador1"
const resultadosBanco = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row && row.apartamento && row.nome);

const moradorDb = resultadosBanco.length === 1 ? resultadosBanco[0] : null;
const multiplosMoradores = resultadosBanco.length > 1;

// Helpers para geração de ID, Protocolo e Data atual (ISO)
const gerarUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
};

const agora = new Date();
const dataColetaISO = agora.toISOString();
const gerarProtocolo = () => {
  const pad = (n) => String(n).padStart(2, '0');
  const dataStr = `${agora.getFullYear()}${pad(agora.getMonth() + 1)}${pad(agora.getDate())}`;
  const rand = Math.floor(1000 + Math.random() * 9000);
  return `ENC-${dataStr}-${rand}`;
};

// 3. Monta o objeto "morador"
const morador = moradorDb
  ? {
      nome: moradorDb.nome ?? null,
      whatsapp: moradorDb.whatsapp ?? null,
      endereco: moradorDb.endereco ?? null,
      apartamento: moradorDb.apartamento ?? null,
      andar: moradorDb.andar ?? null,
      bloco: moradorDb.bloco ?? null,
      complemento: moradorDb.complemento ?? null,
      ativo: moradorDb.ativo ?? true
    }
  : {
      nome: null,
      whatsapp: null,
      endereco: null,
      apartamento: null,
      andar: null,
      bloco: null,
      complemento: null,
      ativo: null
    };

// 4. Monta o objeto "encomenda" com todos os campos preenchidos (exceto data_retirada e codigo_retirada)
const { morador_id: _ignorarIdEnc, ...encomendaLimpa } = base.encomenda || {};

const encomenda = {
  ...encomendaLimpa,
  id: encomendaLimpa.id ?? gerarUUID(),
  protocolo: encomendaLimpa.protocolo ?? gerarProtocolo(),
  codigo_retirada: null,
  status: encomendaLimpa.status ?? (moradorDb ? 'aguardando_retirada' : 'pendente_identificacao'),
  destinatario_nome: encomendaLimpa.destinatario_nome ?? morador.nome ?? null,
  destinatario_apartamento: encomendaLimpa.destinatario_apartamento ?? morador.apartamento ?? null,
  destinatario_bloco: encomendaLimpa.destinatario_bloco ?? morador.bloco ?? null,
  destinatario_andar: encomendaLimpa.destinatario_andar ?? morador.andar ?? null,
  destinatario_endereco: encomendaLimpa.destinatario_endereco ?? morador.endereco ?? null,
  dados_remetente: encomendaLimpa.dados_remetente ?? 'Não informado',
  media_url: encomendaLimpa.media_url ?? base.contexto?.media_url ?? null,
  imagem_legivel: encomendaLimpa.imagem_legivel ?? base.contexto?.imagem_legivel ?? false,
  data_retirada: null,
  data_coleta: dataColetaISO,
  morador_bloco: morador.bloco,
  morador_andar: morador.andar,
  morador_apartamento: morador.apartamento
};

// 5. Monta o objeto "chamado" preservando os campos originais
const { morador_id: _ignorarIdCham, ...chamadoLimpo } = base.chamado || {};
const chamado = {
  ...chamadoLimpo,
  morador_bloco: base.chamado?.data_abertura == null ? null : morador.bloco,
  morador_andar: base.chamado?.data_abertura == null ? null : morador.andar,
  morador_apartamento: base.chamado?.data_abertura == null ? null : morador.apartamento
};

// 6. Entrega o JSON completo na saída
return [
  {
    json: {
      contexto: {
        ...base.contexto,
        morador_encontrado: Boolean(moradorDb),
        multiplos_moradores: multiplosMoradores
      },
      morador,
      encomenda,
      chamado
    }
  }
