const base = { ...$json };
delete base.output;
delete base.text;
delete base.response;

// Busca a flag de legibilidade onde ela realmente está (dentro de contexto ou encomenda)
const legivelContexto = Boolean(
  base.contexto?.imagem_legivel ??
  base.encomenda?.imagem_legivel ??
  base.imagem_legivel ??
  false
);

const rawText = String(
  $json.output ??
  $json.text ??
  $json.response ??
  ''
).trim();

let parsed = {};
let parseSuccess = false;

if (rawText) {
  try {
    const cleanJson = rawText
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();
    parsed = JSON.parse(cleanJson);
    parseSuccess = true;
  } catch (e) {
    parseSuccess = false;
  }
}

// Calcula o booleano real de validação
const validacaoOk = Boolean(
  (parsed.eh_encomenda ?? true) &&
  (parsed.legivel ?? parsed.imagem_legivel ?? legivelContexto)
);

return {
  json: {
    ...base,
    ...parsed,
    validacao_ok: validacaoOk,
    parse_success: parseSuccess
  }
};

// Lê os dados que já chegam estruturados da entrada ($json)
const input = $input.item.json || {};
const contexto = input.contexto || {};
const morador = input.morador || {};
const encomenda = input.encomenda || {};

// Gera ou reaproveita o código único e o código de retirada
const codigo = input.codigo || encomenda.codigo || `ENC-${Math.floor(100000 + Math.random() * 900000)}`;
const codigoRetirada = input.codigo_retirada || encomenda.codigo_retirada || String(Math.floor(1000 + Math.random() * 9000));

// Normaliza o WhatsApp do morador
let moradorWhatsapp = morador.whatsapp || input.morador_whatsapp || null;
if (moradorWhatsapp) {
  const apenasNumeros = String(moradorWhatsapp).replace(/\D/g, '');
  if (apenasNumeros.length >= 10) {
    moradorWhatsapp = apenasNumeros.startsWith('55') ? apenasNumeros : `55${apenasNumeros}`;
  }
}

const moradorEncontrado = Boolean(
  contexto.morador_encontrado ?? (morador.bloco && morador.apartamento && moradorWhatsapp)
);

return {
  json: {
    ...input,
    session: contexto.session || 'default',
    chat_id: contexto.chat_id || '',
    codigo,
    codigo_retirada: codigoRetirada,
